let PLANNER_WEEKENDS_ENABLED=false;
function nextWorkStart(date){const d=new Date(date);while(!PLANNER_WEEKENDS_ENABLED&&(d.getDay()===0||d.getDay()===6))d.setDate(d.getDate()+1);if(d.getHours()<8)d.setHours(8,0,0,0);if(d.getHours()>=17){d.setDate(d.getDate()+1);d.setHours(8,0,0,0);return nextWorkStart(d);}return d;}
function addWorkHours(start,hours){let d=nextWorkStart(start),left=hours;while(left>0){const end=new Date(d);end.setHours(17,0,0,0);const avail=(end-d)/3600000;if(left<=avail){d=new Date(d.getTime()+left*3600000);left=0;}else{left-=avail;d=new Date(end);d.setDate(d.getDate()+1);d.setHours(8,0,0,0);d=nextWorkStart(d);}}return d;}
